--- src/billing/discount.ts ---
import { addCents, applyRateCents, formatCents, type Cents } from "../money.js";

const DISCOUNT_BASIS_POINTS = 1000;

export function discountedTotal(lineItems: Cents[]): string {
  const subtotal = lineItems.reduce(addCents, 0);
  return formatCents(addCents(subtotal, -applyRateCents(subtotal, DISCOUNT_BASIS_POINTS)));
}

